import { useLocation } from "react-router-dom";

function Cart() {
  const location = useLocation();

  const groupedCart = location.state?.groupedCart || [];

  const total = location.state?.total || 0;

  return (
    <div style={{ padding: "30px" }}>
      <h1>Your Cart</h1>

      {groupedCart.length === 0 ? (
        <p>Cart is empty</p>
      ) : (
        <>
          {groupedCart.map((item) => (
            <div
              key={item._id}
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
                border: "1px solid #ddd",
                padding: "15px",
                marginBottom: "15px",
                borderRadius: "10px",
                background: "#fff",
                boxShadow: "0 2px 8px rgba(0,0,0,0.1)",
              }}
            >
              <div>
                <h3>{item.name}</h3>

                <p>
                  ₹{item.price} × {item.qty}
                </p>
              </div>

              <h3>₹{item.price * item.qty}</h3>
            </div>
          ))}

          <div
            style={{
              marginTop: "20px",
              padding: "20px",
              borderRadius: "10px",
              background: "#f5f5f5",
            }}
          >
            <h2>Total: ₹{total}</h2>

            <button
              style={{
                padding: "10px 20px",
                marginRight: "10px",
                cursor: "pointer",
                border: "none",
                borderRadius: "8px",
                background: "green",
                color: "#fff",
              }}
            >
              Place Order
            </button>

            <button
              style={{
                padding: "10px 20px",
                cursor: "pointer",
                border: "none",
                borderRadius: "8px",
                background: "red",
                color: "#fff",
              }}
            >
              Clear Cart
            </button>
          </div>
        </>
      )}
    </div>
  );
}

export default Cart;
